cd /output && python3 - <<'EOF'
import random, subprocess, sys
REF = "/workspace/dataset/test11_executable"
BINS = ["./target/release/test11", "./test11"]
random.seed(42)

def fmt(x):
    return repr(x)

triples = []
# uniform in [-1000, 1000]
for _ in range(300):
    triples.append(tuple(random.uniform(-1000, 1000) for _ in range(3)))
# near zero / tiny magnitudes (exercises scientific notation)
for _ in range(150):
    triples.append(tuple(random.uniform(-1e-3, 1e-3) for _ in range(3)))
for _ in range(100):
    triples.append(tuple(random.uniform(-1e-6, 1e-6) for _ in range(3)))
# large magnitudes (exercises fixed/scientific boundary)
for _ in range(100):
    triples.append(tuple(random.uniform(-1e8, 1e8) for _ in range(3)))
# powers of ten boundaries
for e in range(-10, 12):
    for m in (1.0, 9.999999, 0.0001):
        triples.append((m * 10.0**e, 0.0, 0.0))
# exact halves and rounding-sensitive values
for v in (0.5, 0.25, 0.125, 1e-4, 1e-5, 999999.0, 1000000.0, 999999.5, 0.1, 0.2, 0.3, 1/3):
    triples.append((v, v, v))
    triples.append((-v, 0.0, v))

total = 0
mismatches = []
for b in BINS:
    for t in triples:
        args = [fmt(x) for x in t]
        a = subprocess.run([REF] + args, capture_output=True).stdout
        c = subprocess.run([b] + args, capture_output=True).stdout
        total += 1
        if a != c:
            mismatches.append((b, args, a, c))

print(f"total comparisons: {total} ({len(triples)} triples x {len(BINS)} binaries)")
if mismatches:
    for m in mismatches[:20]:
        print("MISMATCH", m)
    sys.exit(1)
print("ALL MATCH")
EOF

