args.command:
cd /output && perl -e '
my $ref = "/workspace/dataset/test11_executable";
my @bins = ("./target/release/test11", "./test11");
srand(42);
my @triples;
for (1..300) { push @triples, [map { rand()*2000 - 1000 } 1..3]; }
for (1..150) { push @triples, [map { rand()*2e-3 - 1e-3 } 1..3]; }
for (1..100) { push @triples, [map { rand()*2e-6 - 1e-6 } 1..3]; }
for (1..100) { push @triples, [map { rand()*2e8 - 1e8 } 1..3]; }
for my $e (-10..11) { for my $m (1.0, 9.999999, 0.0001) { push @triples, [$m * 10**$e, 0.0, 0.0]; } }
for my $v (0.5, 0.25, 0.125, 1e-4, 1e-5, 999999.0, 1000000.0, 999999.5, 0.1, 0.2, 0.3, 1.0/3.0) {
    push @triples, [$v, $v, $v]; push @triples, [-$v, 0.0, $v];
}
my ($total, $bad) = (0, 0);
for my $bin (@bins) {
    for my $t (@triples) {
        my @a = map { sprintf("%.17g", $_) } @$t;
        my $argstr = join(" ", map { "\x27$_\x27" } @a);
        my $ra = `$ref $argstr`;
        my $rb = `$bin $argstr`;
        $total++;
        if ($ra ne $rb) {
            $bad++;
            print "MISMATCH bin=$bin args=[@a]\n  ref=[$ra]  rust=[$rb]\n" if $bad <= 20;
        }
    }
}
print "total comparisons: $total (" . scalar(@triples) . " triples x " . scalar(@bins) . " binaries)\n";
print $bad ? "MISMATCHES: $bad\n" : "ALL MATCH\n";
exit($bad ? 1 : 0);
'

