cd /output && perl -MIPC::Open3 -MSymbol=gensym -e '
my $ref = "/workspace/dataset/test11_executable";
my @bins = ("./target/release/test11", "./test11");

sub run {
    my ($bin, @args) = @_;
    my $err = gensym;
    my $pid = open3(undef, my $out, $err, $bin, @args);
    local $/;
    my $stdout = <$out> // "";
    my $stderr = <$err> // "";
    waitpid($pid, 0);
    return ($stdout, $stderr, $?);
}

my @cases;
# previously verified happy-path cases
push @cases, [];
push @cases, map { [split] } (
  "0.0 0.0 0.0", "1.0 1.0 1.0", "0.5 0.5 0.5", "0.3 0.7 0.2",
  "1.0 0.0 0.0", "2.0 0.5 0.5", "100 100 100", "0.0001 0 0",
  "-0.5 0 0", "0.333333 0.666667 0.111111", "123456 0 0", "1.0000001 0 0");
# boundary probes
push @cases, map { ["$_", "0", "0"] } (
  "1.17549435e-38", "1.1754942e-38", "5.877e-39", "1e-40", "1e-46",
  "-1e-45", "3.4028235e38", "3.4028236e38", "3.5e38", "1e100", "-1e100",
  "0", "-0", "0x1p-126", "0x1p-127", "0x1p-149", "0x1p-150", "0x1.8p-149");
# lenient-parse cases
push @cases, ["  0.5", "0", "0"], ["0x1p-1", "0", "0"], ["5x", "0", "0"],
  ["1,5", "0", "0"], ["1_000", "0", "0"], ["1e", "0", "0"], ["abc", "0", "0"],
  ["", "0", "0"], ["5.", "0", "0"], [".5", "0", "0"], ["5.e3", "0", "0"],
  ["0x", "0", "0"], ["0xg", "0", "0"], ["+1.5", "0", "0"], ["INF", "0", "0"],
  ["infinity", "0", "0"], ["0x1.8p1", "0", "0"], ["0X1P-2", "0", "0"],
  ["  -0x1.4p+3xyz", "0", "0"], ["1e400", "0", "0"], ["0x1p2000", "0", "0"],
  ["0x1p-2000", "0", "0"], ["0x0p5", "0", "0"], [".", "0", "0"], ["+", "0", "0"];
# NaN cases
push @cases, ["inf", "-inf", "0.5"], ["-inf", "inf", "0.5"],
  ["nan", "0", "0"], ["inf", "0", "0"], ["-nan", "0", "0"],
  ["nan", "inf", "-inf"], ["-nan", "1", "2"];

my ($total, $bad) = (0, 0);
for my $bin (@bins) {
    for my $c (@cases) {
        my ($ro, $re, $rs) = run($ref, @$c);
        my ($bo, $be, $bs) = run($bin, @$c);
        $total++;
        # abort cases: stdout empty + same exit status; stderr must carry message
        my $ok = ($ro eq $bo && $rs == $bs);
        if ($ok && ($rs & 127) == 6) {
            $ok = $be =~ /^terminate called after throwing an instance of \x27std::(out_of_range|invalid_argument)\x27\n  what\(\):  stof\n/;
            # also check exception class matches the reference
            my ($rcls) = $re =~ /std::(out_of_range|invalid_argument)/;
            my ($bcls) = $be =~ /std::(out_of_range|invalid_argument)/;
            $ok &&= defined $rcls && defined $bcls && $rcls eq $bcls;
        }
        if (!$ok) {
            $bad++;
            if ($bad <= 15) {
                print "MISMATCH bin=$bin args=[", join("|", @$c), "]\n";
                print "  ref:  rc=$rs out=[$ro] err=[$re]\n";
                print "  rust: rc=$bs out=[$bo] err=[$be]\n";
            }
        }
    }
}
print "targeted cases: $total comparisons, mismatches: $bad\n";
exit($bad ? 1 : 0);
'

