        my $r = rand();
        if    ($r < 0.35) { push @a, sprintf("%.8g", (rand()*1e5+3.5)*10**38 * (rand()<0.5?-1:1)); }
        elsif ($r < 0.75) { push @a, sprintf("%.8g", rand()*1.1e-38 * (rand()<0.5?-1:1)); }
        else              { push @a, sprintf("%.8g", rand()*1e-42 * (rand()<0.5?-1:1)); }
    }
    push @argsets, \@a;
}
# near-boundary fuzz: around FLT_MIN and FLT_MAX
for (1..60) {
    my $base = rand() < 0.5 ? 1.1754943e-38 : 3.4028235e38;
    push @argsets, [sprintf("%.10g", $base * (1 + (rand()*4-2)*1e-6)), "0", "0"];
}
# lenient-grammar fuzz: hex floats, prefixes, whitespace, garbage suffixes
for (1..60) {
    my $r = rand();
    my $s;
    if    ($r < 0.3) { $s = sprintf("0x%x.%xp%d", int(rand(256)), int(rand(0x10000)), int(rand(300))-150); }
    elsif ($r < 0.5) { $s = (" ", "\t", "")->[int(rand(3))] . sprintf("%.6g", rand()*200-100) . ("x", ",5", "_9", "e", ".", "")->[int(rand(6))]; }
    elsif ($r < 0.7) { $s = sprintf("%.10g", rand()*2-1); }
    elsif ($r < 0.8) { $s = sprintf("%d", int(rand(1e9))); }
    elsif ($r < 0.9) { $s = ("inf","-inf","nan","-nan","INFINITY","NaN")->[int(rand(6))]; }
    else             { $s = sprintf(".%d", int(rand(1e6))); }
    push @argsets, [$s, "0.25", "0.75"];
}
# powers-of-ten and rounding-sensitive
for my $e (-46..40) {
    for my $m ("1", "9.999999", "1.17549435", "3.4028235") {
        push @argsets, ["${m}e$e", "0", "0"];
    }
}

my ($total, $bad) = (0, 0);
for my $bin (@bins) {
    for my $c (@argsets) {
        my ($ro, $rs) = run($ref, @$c);
        my ($bo, $bs) = run($bin, @$c);
        $total++;
        if ($ro ne $bo || $rs != $bs) {
            $bad++;
            if ($bad <= 15) {
                print "MISMATCH bin=$bin args=[", join("|", @$c), "]\n";
                print "  ref:  rc=$rs out=[$ro]\n  rust: rc=$bs out=[$bo]\n";
            }
        }
    }
}
print "fuzz: $total comparisons (", scalar(@argsets), " arg sets x ", scalar(@bins), " binaries), mismatches: $bad\n";
exit($bad ? 1 : 0);
'

